let state={view:'Today',coach:true,goalOpen:true,filter:'All commitments',events:structuredClone(defaultEvents),ledger:structuredClone(ledgerSeed),proposal:true,newGoals:[],loops:[],dayOffset:0,dayMode:false,completed:0};
try{const saved=JSON.parse(localStorage.getItem('kairos-design-v1')||'null');if(saved)Object.assign(state,saved,{view:'Today',coach:true});}catch{}
let timer={running:false,paused:false,remaining:25*60,startedAt:null,base:25*60,task:'Customer research',event:'research'};
try{const savedTimer=JSON.parse(localStorage.getItem('kairos-design-timer')||'null');if(savedTimer&&savedTimer.running&&savedTimer.startedAt)timer=savedTimer;}catch{}
